import {
    lit,
    MaterialPlugin,
    materialType,
} from "@dylanebert/shallot/standard/rendering";
import tgpu from "typegpu";
import * as d from "typegpu/data";
import * as std from "typegpu/std";

/** Bands per unit of local distance along the stripe direction. */
export const stripeDensity = 4;
/** Bands travelled per second. */
export const stripeSpeed = 0.6;
/** Diagonal stripe direction in the cube's local space, so bands wrap continuously across faces. */
export const stripeDirection = d.vec3f(1, 1, 0.35);

/** 0 on a dark band, 1 on a light band, with a narrow soft edge between them. */
export const stripe = tgpu.fn(
    [d.vec3f, d.f32],
    d.f32,
)((localPos, time) => {
    "use gpu";
    const phase = std.dot(localPos, stripeDirection) * stripeDensity - time * stripeSpeed;
    const wave = std.sin(phase * 6.2831853);
    return std.smoothstep(-0.15, 0.15, wave);
});

export const StripeParameters = d.struct({
    time: d.f32,
    darkColor: d.vec3f,
    lightColor: d.vec3f,
});

export const StripeMaterial = materialType({
    name: "MovingStripes",
    parameters: StripeParameters,
    defaults: { time: 0, darkColor: d.vec3f(0.05, 0.04, 0.035), lightColor: d.vec3f(0.72, 0.4, 0.05) },
    fragmentInputs: { localPos: true },
    fragment: (ctx) => {
        "use gpu";
        const value = stripe(ctx.localPos, ctx.parameters.time);
        const color = std.mix(ctx.parameters.darkColor, ctx.parameters.lightColor, value);
        return d.vec4f(lit(color, ctx.worldNormal), 1);
    },
});

export const StripePlugin = MaterialPlugin(StripeMaterial);
