import { expect, setDefaultTimeout, test } from "bun:test";
import { lookAtRotation } from "@dylanebert/shallot";
import { MeshInstance } from "@dylanebert/shallot/mesh";
import {
    attachTexture,
    Camera,
    captureTexture,
    DirectionalLight,
    Tonemapping,
    TonemappingMethod,
} from "@dylanebert/shallot/rendering";
import {
    MeshMaterial,
    MeshRenderPlugin,
    StandardRenderer,
    StandardRenderingPlugin,
} from "@dylanebert/shallot/standard/rendering";
import { TIMEOUT } from "@dylanebert/shallot/testing";
import { openGpuApp } from "@dylanebert/shallot/testing/gpu";
import { Transform } from "@dylanebert/shallot/transform";
import { StripeMaterial, StripePlugin } from "../src/stripes/material";

setDefaultTimeout(TIMEOUT.node);

const size = 64;

test("the rendered cube face shows bands that shift as time advances", async () => {
    let camera = 0;
    let handle!: ReturnType<(typeof StripeMaterial)["add"]> extends infer H ? H : never;
    const app = await openGpuApp({
        defaults: false,
        plugins: [
            {
                name: "StripeScene",
                dependencies: [StandardRenderingPlugin, MeshRenderPlugin, StripePlugin],
                initialize(world) {
                    camera = world.create();
                    world.add(camera, Transform, { translation: [0, 0, 1.6] });
                    world.add(camera, Camera, { antialias: 0 });
                    world.add(camera, StandardRenderer);
                    world.add(camera, Tonemapping, { method: TonemappingMethod.None });
                    attachTexture(world, camera, { width: size, height: size });
                    const sun = world.create();
                    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 0, 0, -1) });
                    world.add(sun, DirectionalLight, { illuminance: 4000 });
                    handle = world.resource(StripeMaterial).add({ time: 0 });
                    const cube = world.create();
                    world.add(cube, Transform);
                    world.add(cube, MeshInstance);
                    world.add(cube, MeshMaterial, handle);
                },
            },
        ],
    });
    try {
        const { world } = app;
        const shot = async (time: number) => {
            world.resource(StripeMaterial).update(handle, { time });
            world.step(0);
            world.step(0);
            const { rgba } = await captureTexture(world, camera);
            const reds: number[] = [];
            for (let y = 20; y < 44; y++)
                for (let x = 20; x < 44; x++) reds.push(rgba[(y * size + x) * 4]!);
            return reds;
        };
        const before = await shot(0);
        const after = await shot(0.8);
        const dark = Math.min(...before);
        const light = Math.max(...before);
        console.log("stripe contrast", { dark, light });
        expect(light - dark, "light and dark bands on the face").toBeGreaterThan(60);
        const changed = before.filter((value, i) => Math.abs(value - after[i]!) > 30).length;
        console.log("pixels changed after 0.8s", changed, "of", before.length);
        expect(changed, "bands moved").toBeGreaterThan(before.length / 10);
    } finally {
        app.dispose();
    }
});
